package com.secure.documentwallet;

import android.content.*;import android.net.Uri;import org.json.*;import java.io.*;import java.util.*;

final class VaultRepository {
 static final String INDEX="index";private final Context c;private final CryptoStore crypto;
 VaultRepository(Context c){this.c=c.getApplicationContext();crypto=new CryptoStore(c);}
 synchronized JSONArray all()throws Exception{File f=new File(crypto.vaultDir(),INDEX+".sdw");return f.exists()?new JSONArray(new String(crypto.decrypt(f),java.nio.charset.StandardCharsets.UTF_8)):new JSONArray();}
 synchronized JSONObject get(String id)throws Exception{JSONArray a=all();for(int i=0;i<a.length();i++)if(id.equals(a.getJSONObject(i).optString("id")))return a.getJSONObject(i);return null;}
 synchronized JSONObject add(String title,String category,List<Uri> pages)throws Exception{return add(title,category,pages,null,null,null,false);}
 synchronized JSONObject add(String title,String category,List<Uri> pages,Uri original,String originalMime,String originalName,boolean pdfCompanionPreview)throws Exception{String id=UUID.randomUUID().toString(),searchText=OcrIndexer.read(c,pages);JSONArray stored=new JSONArray();String originalStored=null;try{for(int i=0;i<pages.size();i++){String name=id+"-page-"+(i+1);try(InputStream in=c.getContentResolver().openInputStream(pages.get(i))){if(in==null)throw new IOException("Cannot read scanned page");crypto.encrypt(in,name);}stored.put(name);}if(original!=null){originalStored=id+"-original";try(InputStream in=c.getContentResolver().openInputStream(original)){if(in==null)throw new IOException("Cannot read original document");crypto.encrypt(in,originalStored);}}JSONObject d=new JSONObject().put("id",id).put("title",title).put("category",category).put("createdAt",System.currentTimeMillis()).put("pages",stored);if(!searchText.isEmpty())d.put("searchText",searchText);if(originalStored!=null)d.put("original",originalStored).put("originalMime",originalMime==null?"application/octet-stream":originalMime).put("originalName",originalName==null?title:originalName);if(pdfCompanionPreview)d.put("previewMime","application/pdf");JSONArray a=all();a.put(d);save(a);return d;}catch(Exception e){for(int i=0;i<stored.length();i++)crypto.delete(stored.optString(i));if(originalStored!=null)crypto.delete(originalStored);throw e;}}
 synchronized void rename(String id,String title,String category)throws Exception{JSONArray a=all();for(int i=0;i<a.length();i++){JSONObject d=a.getJSONObject(i);if(id.equals(d.optString("id"))){d.put("title",title);d.put("category",category);break;}}save(a);}
 synchronized void updateDetails(String id,String issuer,String number,String issueDate,String expiryDate,String tags,String notes)throws Exception{JSONArray a=all();for(int i=0;i<a.length();i++){JSONObject d=a.getJSONObject(i);if(id.equals(d.optString("id"))){d.put("issuer",issuer).put("documentNumber",number).put("issueDate",issueDate).put("expiryDate",expiryDate).put("tags",tags).put("notes",notes).put("updatedAt",System.currentTimeMillis());break;}}save(a);}
 synchronized int verifyAll()throws Exception{File[] files=crypto.vaultDir().listFiles((d,n)->n.endsWith(".sdw"));if(files==null)return 0;int count=0;for(File file:files){crypto.decrypt(file);count++;}return count;}
 synchronized void replacePage(String id,int pageIndex,String title,Uri replacement)throws Exception{JSONArray a=all();String fresh=id+"-page-"+(pageIndex+1)+"-"+System.currentTimeMillis();try(InputStream in=c.getContentResolver().openInputStream(replacement)){if(in==null)throw new IOException("Cannot read edited page");crypto.encrypt(in,fresh);}String old=null;boolean found=false;for(int i=0;i<a.length();i++){JSONObject d=a.getJSONObject(i);if(id.equals(d.optString("id"))){JSONArray pages=d.getJSONArray("pages");if(pageIndex<0||pageIndex>=pages.length())throw new IndexOutOfBoundsException("Page not found");old=pages.getString(pageIndex);pages.put(pageIndex,fresh);d.put("title",title);found=true;break;}}if(!found){crypto.delete(fresh);throw new IOException("Document not found");}try{save(a);if(old!=null)crypto.delete(old);}catch(Exception error){crypto.delete(fresh);throw error;}}
 synchronized void delete(String id)throws Exception{JSONArray source=all(),out=new JSONArray();for(int i=0;i<source.length();i++){JSONObject d=source.getJSONObject(i);if(id.equals(d.optString("id"))){JSONArray pages=d.optJSONArray("pages");for(int j=0;pages!=null&&j<pages.length();j++)crypto.delete(pages.optString(j));String original=d.optString("original");if(!original.isEmpty())crypto.delete(original);}else out.put(d);}save(out);}
 byte[] page(JSONObject d,int index)throws Exception{return crypto.decrypt(new File(crypto.vaultDir(),d.getJSONArray("pages").getString(index)+".sdw"));}
 byte[] original(JSONObject d)throws Exception{String name=d.optString("original");if(name.isEmpty())throw new IOException("No original file is stored");return crypto.decrypt(new File(crypto.vaultDir(),name+".sdw"));}
 void rekey(String oldPin,String newPin,byte[] salt)throws Exception{crypto.rekey(oldPin,newPin,salt);}
 private void save(JSONArray a)throws Exception{crypto.encryptBytes(a.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),INDEX);}
}
